"""The agent harness: a model in a tool loop, driving browsers through Playwright MCP.

The model (the hosted Qwen, OpenAI-compatible) chooses every navigation, search and document; this module only
relays its tool calls. Each browser gets its own Playwright MCP server attached over CDP to one of the run's
browsers, so tool names are prefixed by the browser's name (`tender__browser_click`). Local tools let the model
save what it found (`save_facts`), read a file it downloaded (`read_file`) and stop (`finish`).
"""
from __future__ import annotations

import asyncio
import io
import json
import os
import re
import time
import zipfile
from contextlib import AsyncExitStack
from pathlib import Path

from mcp import ClientSession, StdioServerParameters
from mcp.client.stdio import stdio_client
from openai import AsyncOpenAI

HERE = Path(__file__).resolve().parent
PLAYWRIGHT_MCP = HERE / "node_modules" / ".bin" / "playwright-mcp"

# The browser tools a site agent needs; the rest (install, resize, ...) only add noise for the model.
BROWSER_TOOLS = {
    "browser_navigate", "browser_navigate_back", "browser_snapshot", "browser_click", "browser_type",
    "browser_fill_form", "browser_select_option", "browser_press_key", "browser_hover", "browser_wait_for",
    "browser_handle_dialog", "browser_tabs", "browser_evaluate", "browser_file_upload",
}
MAX_RESULT_CHARS = 14000     # one tool result as the model sees it
OLD_RESULT_CHARS = 600       # older browser results, once newer ones exist
KEEP_FULL_RESULTS = 2        # the latest browser results stay whole
CALL_TIMEOUT_S = 240
SNAPSHOT_LINK = re.compile(r"\[Snapshot\]\(([^)]+\.yml)\)")


def qwen_client() -> AsyncOpenAI:
    return AsyncOpenAI(base_url=os.environ["QWEN_BASE_URL"], api_key=os.environ.get("QWEN_API_KEY", "local"),
                       timeout=CALL_TIMEOUT_S, max_retries=3)


def read_document(path: Path, limit: int = 30000) -> str:
    """Text of a downloaded file: ZIPs listed and their text members read, PDFs extracted, the rest decoded."""
    data = path.read_bytes()
    if zipfile.is_zipfile(io.BytesIO(data)):
        out = []
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            for name in archive.namelist():
                inner = archive.read(name)
                out.append(f"--- {name} ---\n{_bytes_to_text(name, inner)}")
        return "\n".join(out)[:limit]
    return _bytes_to_text(path.name, data)[:limit]


def _bytes_to_text(name: str, data: bytes) -> str:
    if name.lower().endswith(".pdf") or data[:4] == b"%PDF":
        from pypdf import PdfReader
        return "\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(data)).pages)
    for encoding in ("utf-8", "cp1252"):
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", errors="replace")


class Agent:
    """One model session with tools over named browsers. Use `async with Agent(...) as agent: await agent.run(...)`."""

    def __init__(self, name: str, browsers: dict[str, str], workdir: Path, model: str = "qwen"):
        self.name, self.browsers, self.model = name, browsers, model
        self.dir = workdir / name
        self.downloads = self.dir / "downloads"
        self.downloads.mkdir(parents=True, exist_ok=True)
        self.facts_path = self.dir / "facts.json"
        self.log = (self.dir / "transcript.jsonl").open("w")
        self.sessions: dict[str, ClientSession] = {}
        self.tools: list[dict] = []
        self.client = qwen_client()
        self.facts = None
        self.finished = None
        self.required: list[str] = []
        self.usage = {"calls": 0, "prompt_tokens": 0, "completion_tokens": 0}
        self._stack = AsyncExitStack()

    async def __aenter__(self):
        try:
            for browser, cdp_url in self.browsers.items():
                params = StdioServerParameters(command=str(PLAYWRIGHT_MCP), cwd=str(self.dir), args=[
                    "--cdp-endpoint", cdp_url, "--output-dir", str(self.downloads), "--image-responses", "omit",
                    "--timeout-action", "10000"])
                read, write = await self._stack.enter_async_context(stdio_client(params))
                session = await self._stack.enter_async_context(ClientSession(read, write))
                await asyncio.wait_for(session.initialize(), 60)
                self.sessions[browser] = session
                for tool in (await asyncio.wait_for(session.list_tools(), 60)).tools:
                    if tool.name in BROWSER_TOOLS:
                        self.tools.append(_openai_tool(f"{browser}__{tool.name}", tool.description,
                                                       tool.input_schema))
        except BaseException:
            await self.__aexit__()
            raise
        self.tools += LOCAL_TOOLS
        return self

    async def __aexit__(self, *exc):
        self.log.close()
        await self._stack.aclose()

    def _print(self, text: str):
        print(f"[{self.name}] {text}", flush=True)

    async def run(self, system: str, task: str, deadline: float, max_turns: int = 80,
                  required: list[str] | None = None, progress_checks: bool = True) -> dict:
        """Loop until the model calls finish, the turns run out or `deadline` (time.monotonic()) passes.
        `required`: top-level keys the saved facts must have; the model is reminded of missing ones and cannot
        finish without them (unless time runs out)."""
        self.required = required or []
        messages = [{"role": "system", "content": system}, {"role": "user", "content": task}]
        started, nudged = time.monotonic(), False
        for turn in range(max_turns):
            left = deadline - time.monotonic()
            if left < 5:
                self._print("deadline reached")
                break
            if left < 60 and not nudged:
                messages.append({"role": "user", "content": "Less than a minute left: save_facts with everything you "
                                 "have now, then finish."})
                nudged = True
            if progress_checks and turn and turn % 10 == 0:
                missing = missing_keys(self.facts, self.required)
                messages.append({"role": "user", "content": "Progress check: call save_facts now with everything "
                                 "you found so far." + (f" Still missing: {', '.join(missing)}." if missing else "")})
            _compact(messages)
            try:
                response = await asyncio.wait_for(self.client.chat.completions.create(
                    model=self.model, messages=messages, tools=self.tools, temperature=0.2), timeout=min(left, 300))
            except (asyncio.TimeoutError, Exception) as error:  # noqa: BLE001  keep the facts saved so far
                self._print(f"model call failed: {error!r}")
                break
            self._count(response)
            message = response.choices[0].message
            messages.append(_assistant_message(message))
            self.log.write(json.dumps({"turn": turn, "assistant": messages[-1]}, ensure_ascii=False) + "\n")
            if not message.tool_calls:
                if self.finished is not None:
                    break
                messages.append({"role": "user", "content": "Continue with the tools. When you are done, call "
                                 "save_facts with everything you found, then finish."})
                continue
            for call in message.tool_calls:
                result = await self._call(call.function.name, call.function.arguments)
                self._print(f"{time.monotonic() - started:5.0f}s {call.function.name} {_loggable(call)}")
                messages.append({"role": "tool", "tool_call_id": call.id, "name": call.function.name,
                                 "content": result[:MAX_RESULT_CHARS]})
                self.log.write(json.dumps({"turn": turn, "tool": call.function.name, "result": result[:3000]},
                                          ensure_ascii=False) + "\n")
            if self.finished is not None:
                break
        self.log.flush()
        return {"name": self.name, "seconds": round(time.monotonic() - started), "facts": self.facts,
                "summary": self.finished, "usage": self.usage}

    def _count(self, response):
        self.usage["calls"] += 1
        if response.usage:
            self.usage["prompt_tokens"] += response.usage.prompt_tokens or 0
            self.usage["completion_tokens"] += response.usage.completion_tokens or 0

    async def _call(self, name: str, arguments: str) -> str:
        try:
            args = json.loads(arguments or "{}")
        except ValueError:
            return f"Error: the arguments are not valid JSON: {arguments[:200]}"
        if name == "save_facts":
            self.facts = args.get("facts", args)
            self.facts_path.write_text(json.dumps(self.facts, ensure_ascii=False, indent=2))
            missing = missing_keys(self.facts, self.required)
            return "Saved." + (f" Still missing: {', '.join(missing)}." if missing else (
                " Everything required is there: finish now, unless a value you know exists is still unread."))
        if name == "finish":
            missing = missing_keys(self.facts, self.required)
            if missing:
                return (f"Not finished: the saved facts have no {', '.join(missing)}. Collect them, call "
                        "save_facts with the complete JSON, then finish.")
            self.finished = args.get("summary", "")
            return "Finished."
        if name == "read_file":
            return self._read_file(args.get("name", ""))
        browser, _, tool = name.partition("__")
        session = self.sessions.get(browser)
        if session is None or tool not in BROWSER_TOOLS:
            return f"Error: unknown tool {name}"
        try:
            result = await asyncio.wait_for(session.call_tool(tool, args), timeout=90)
        except Exception as error:  # noqa: BLE001  the model decides how to recover
            return f"Error: {error!r}"
        text = "\n".join(getattr(part, "text", "") for part in result.content if getattr(part, "type", "") == "text")
        return self._inline_files(text) or "(no text result)"

    def _inline_files(self, text: str) -> str:
        """Playwright MCP sometimes links a snapshot file instead of including it: put the page into the result."""
        def inline(match):
            path = Path(match.group(1))
            path = path if path.is_absolute() else self.dir / path
            try:
                return "```yaml\n" + path.read_text()[:MAX_RESULT_CHARS] + "\n```"
            except OSError:
                return match.group(0)
        return SNAPSHOT_LINK.sub(inline, text)

    def _read_file(self, name: str) -> str:
        files = sorted(p for p in self.downloads.rglob("*") if p.is_file())
        if not name:
            return "Downloaded files:\n" + "\n".join(p.name for p in files) if files else "No files downloaded yet."
        match = next((p for p in files if p.name == name or str(p).endswith(name)), None)
        if match is None:
            return f"No downloaded file named {name}. Downloaded: {[p.name for p in files]}"
        try:
            return read_document(match)
        except Exception as error:  # noqa: BLE001
            return f"Error reading {name}: {error!r}"


LOCAL_TOOLS = [
    {"type": "function", "function": {
        "name": "save_facts",
        "description": "Save everything you found so far as one JSON object (replaces the previous save). Save "
                       "often, so your work survives if you are stopped.",
        "parameters": {"type": "object", "properties": {"facts": {"type": "object"}}, "required": ["facts"]}}},
    {"type": "function", "function": {
        "name": "read_file",
        "description": "Read a file the browser downloaded (ZIP, PDF, CSV, text). Without a name, list them.",
        "parameters": {"type": "object", "properties": {"name": {"type": "string"}}}}},
    {"type": "function", "function": {
        "name": "finish",
        "description": "Stop working. Call save_facts first.",
        "parameters": {"type": "object", "properties": {"summary": {"type": "string"}}, "required": ["summary"]}}},
]


def _loggable(call) -> str:
    """A tool call for the log, without what is typed into forms (logins, TANs)."""
    if call.function.name.endswith(("browser_fill_form", "browser_type")):
        try:
            args = json.loads(call.function.arguments or "{}")
        except ValueError:
            return "(form input)"
        fields = args.get("fields") or [args]
        return "(form input: " + ", ".join(str(f.get("name") or f.get("element") or "?") for f in fields)[:100] + ")"
    return call.function.arguments[:100]


def _openai_tool(name: str, description: str | None, schema: dict | None) -> dict:
    schema = dict(schema or {"type": "object", "properties": {}})
    schema.pop("$schema", None)
    return {"type": "function", "function": {"name": name, "description": (description or "")[:1000],
                                             "parameters": schema}}


def _assistant_message(message) -> dict:
    out = {"role": "assistant", "content": message.content or ""}
    if message.tool_calls:
        out["tool_calls"] = [{"id": c.id, "type": "function",
                              "function": {"name": c.function.name, "arguments": c.function.arguments}}
                             for c in message.tool_calls]
    return out


def _compact(messages: list[dict]):
    """Old page snapshots dominate the context: keep the latest few whole, shorten the older ones. Results that
    carry data the model asked for (evaluate, read_file) stay, so it never has to read a page twice."""
    snapshots = [m for m in messages if m["role"] == "tool" and "__browser_" in m.get("name", "")
                 and not m["name"].endswith("browser_evaluate") and "```yaml" in m["content"]]
    for message in snapshots[:-KEEP_FULL_RESULTS]:
        if len(message["content"]) > OLD_RESULT_CHARS:
            message["content"] = message["content"][:OLD_RESULT_CHARS] + "\n[... older page snapshot shortened]"


def missing_keys(facts, required: list[str]) -> list[str]:
    """Required top-level keys that are absent or empty in the saved facts."""
    facts = facts if isinstance(facts, dict) else {}
    return [key for key in required if facts.get(key) in (None, "", [], {})]

content.content:
"""The bid arithmetic: resolved facts in, the answer's numbers out. Pure functions, no browser, no model.

Every input here has already been chosen by the site agents and checked by the resolver: the final quantity, the
matched material, the valid price condition, the governing approval and so on. This module only applies the brief's
calculation rules to them, in Decimal, rounding HALF_UP to cents exactly where the brief says.
"""
from __future__ import annotations

import math
from dataclasses import dataclass, field
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
ZERO = Decimal("0")

# Which parts of the unit price a Konditionsgruppe lets the order discount reduce. Setup fees never.
SCOPE_BASE = "base"
SCOPE_BASE_AND_SURCHARGE = "base_and_surcharge"
SCOPE_NONE = "none"
SCOPES = (SCOPE_BASE, SCOPE_BASE_AND_SURCHARGE, SCOPE_NONE)


def cents(value: Decimal) -> Decimal:
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def D(value) -> Decimal:
    return value if isinstance(value, Decimal) else Decimal(str(value))


# --- inputs -------------------------------------------------------------------------------------------------------

@dataclass
class PriceScale:
    min_quantity: int
    price: Decimal  # in the condition's currency, per `price_unit` pieces


@dataclass
class PriceCondition:
    scales: list[PriceScale]
    currency: str = "EUR"
    price_unit: int = 1             # pieces the scale price is quoted for (e.g. per 100)
    eur_per_unit: Decimal = Decimal(1)  # EUR per one unit of `currency`, from the Devisenfixing


@dataclass
class Commitment:
    """A Terminfreigabe delivery commitment assigned to a position by the tender Q&A."""
    material: str
    ceiling: int        # pooled final pieces of that material, inclusive
    lead_time_weeks: int


@dataclass
class Line:
    position: str
    quantity: int                         # final pieces
    material: str | None                  # None: no active matching material, so the whole bid is no_bid
    condition: PriceCondition | None = None
    stock: int = 0                        # pieces on stock of this material (shared by its positions)
    stock_lead_time_weeks: int = 0
    production_lead_time_weeks: int = 0
    commitment: Commitment | None = None
    mass_surcharge_per_unit: Decimal = ZERO   # EUR per piece, unrounded, before any discount
    setup_fee: Decimal = ZERO                 # ordinary setup fee for the position, EUR
    discount_scope: str = SCOPE_BASE          # from the position's Konditionsgruppe; default base only
    carton_size: int | None = None            # pieces per carton (ERP)
    carton_price: Decimal = ZERO              # EUR per carton (Verpackungstarif)
    setup_pool: bool = False                  # member of the shared setup pool (Rüstpool)
    allocation_mass: Decimal = ZERO           # ERP allocation mass per piece (not the surcharge mass)
    bonus_eligible: bool = False              # member of the project bonus


@dataclass
class Approval:
    percent: Decimal
    min_order_value: Decimal | None = None   # inclusive threshold on the undiscounted net order value


@dataclass
class BonusBand:
    lower: Decimal              # EUR, the band applies to the part of the total above this ...
    upper: Decimal | None       # ... up to this (None: no upper bound)
    percent: Decimal


@dataclass
class Order:
    tender_reference: str
    lines: list[Line]
    approval: Approval | None = None
    setup_pool_fee: Decimal = ZERO
    bonus_bands: list[BonusBand] = field(default_factory=list)


# --- the rules ----------------------------------------------------------------------------------------------------

def scale_price(condition: PriceCondition, quantity: int) -> Decimal:
    """The scale with the highest minimum quantity no greater than the quantity, normalized to one piece and
    converted to EUR, HALF_UP to cents. This is base_unit_price; everything after uses it."""
    eligible = [s for s in condition.scales if s.min_quantity <= quantity]
    if not eligible:
        raise ValueError(f"no price scale reaches quantity {quantity}")
    scale = max(eligible, key=lambda s: s.min_quantity)
    per_piece = D(scale.price) / D(condition.price_unit)
    return cents(per_piece * D(condition.eur_per_unit))


def discount_percent(order: Order, base_prices: dict[str, Decimal]) -> Decimal:
    """The approved percentage, or 0 if its minimum order value (undiscounted goods, no surcharges or setup,
    rounded to cents, inclusive) is not reached. No fallback to older approvals: the resolver passes only the latest."""
    if order.approval is None:
        return ZERO
    if order.approval.min_order_value is not None:
        value = cents(sum((line.quantity * base_prices[line.position] for line in order.lines), ZERO))
        if value < D(order.approval.min_order_value):
            return ZERO
    return D(order.approval.percent)


def pooled_demand(lines: list[Line]) -> dict[str, int]:
    demand: dict[str, int] = {}
    for line in lines:
        demand[line.material] = demand.get(line.material, 0) + line.quantity
    return demand


def lead_time(line: Line, demand: dict[str, int]) -> int:
    """A matching commitment within its ceiling wins; otherwise stock delivery only if stock covers the pooled
    demand of every position on that material, else production."""
    pooled = demand[line.material]
    c = line.commitment
    if c is not None and c.material == line.material and pooled <= c.ceiling:
        return c.lead_time_weeks
    return line.stock_lead_time_weeks if line.stock >= pooled else line.production_lead_time_weeks


def packaging_cost(line: Line) -> Decimal:
    if not line.carton_size:
        return ZERO
    return math.ceil(line.quantity / line.carton_size) * D(line.carton_price)


def allocate_cents(total: Decimal, weights: dict[str, Decimal]) -> dict[str, Decimal]:
    """Split `total` (whole cents) proportionally to `weights` by largest remainders; ties go to the ascending
    position identifier."""
    total_cents = int((D(total) / CENT).to_integral_value(rounding=ROUND_HALF_UP))
    weight_sum = sum(weights.values(), ZERO)
    if total_cents == 0 or weight_sum == 0:
        return {key: ZERO for key in weights}
    exact = {key: Decimal(total_cents) * w / weight_sum for key, w in weights.items()}
    floors = {key: int(v) for key, v in exact.items()}
    left = total_cents - sum(floors.values())
    by_remainder = sorted(weights, key=lambda key: (-(exact[key] - floors[key]), _position_key(key)))
    for key in by_remainder[:left]:
        floors[key] += 1
    return {key: Decimal(c) * CENT for key, c in floors.items()}


def _position_key(position: str):
    """Ascending position identifier: numeric parts compared as numbers ("2" before "10", "1.2" before "1.10")."""
    return tuple(int(part) if part.isdigit() else part for part in position.replace("-", ".").split("."))


def project_bonus(bands: list[BonusBand], eligible_total: Decimal) -> Decimal:
    """Marginal bands: each percentage applies only to the part of the total inside its band. HALF_UP to cents."""
    credit = ZERO
    for band in bands:
        upper = eligible_total if band.upper is None else min(eligible_total, D(band.upper))
        portion = upper - D(band.lower)
        if portion > 0:
            credit += portion * D(band.percent) / 100
    return cents(credit)


@dataclass
class PricedLine:
    position: str
    material_number: str
    quantity: int
    unit_price: Decimal
    lead_time_weeks: int
    base_unit_price: Decimal
    surcharge_per_unit: Decimal
    packaging_per_unit: Decimal
    rebate_total: Decimal


def no_bid(tender_reference: str) -> dict:
    """No positions, a total of zero, and 0 % (a conditional approval yields 0 % for no_bid)."""
    return {"tender_reference": tender_reference, "decision": "no_bid", "currency": "EUR",
            "discount_percent": 0, "positions": [], "total_net": 0}


def price_order(order: Order) -> dict:
    """The answer: a bid with one entry per position, or no_bid when any position lacks an active material."""
    if any(line.material is None for line in order.lines):
        return no_bid(order.tender_reference)
    for line in order.lines:
        if line.discount_scope not in SCOPES:
            raise ValueError(f"position {line.position}: unknown discount scope {line.discount_scope!r}")
        if line.quantity <= 0:
            raise ValueError(f"position {line.position}: quantity {line.quantity}")

    base = {line.position: scale_price(line.condition, line.quantity) for line in order.lines}
    pct = discount_percent(order, base)
    factor = 1 - pct / 100
    demand = pooled_demand(order.lines)

    pool = allocate_cents(order.setup_pool_fee, {
        line.position: line.quantity * D(line.allocation_mass) for line in order.lines if line.setup_pool})
    goods = {line.position: line.quantity * base[line.position] for line in order.lines if line.bonus_eligible}
    bonus = allocate_cents(project_bonus(order.bonus_bands, sum(goods.values(), ZERO)), goods) if goods else {}

    priced = []
    for line in order.lines:
        q = Decimal(line.quantity)
        surcharge = D(line.mass_surcharge_per_unit)
        setup = D(line.setup_fee) + pool.get(line.position, ZERO)
        packaging = packaging_cost(line)
        rebate = bonus.get(line.position, ZERO)
        discounted_base = base[line.position] * (factor if line.discount_scope != SCOPE_NONE else 1)
        discounted_surcharge = surcharge * (factor if line.discount_scope == SCOPE_BASE_AND_SURCHARGE else 1)
        unit_price = cents(discounted_base + discounted_surcharge + (setup + packaging - rebate) / q)
        priced.append(PricedLine(
            position=line.position,
            material_number=line.material,
            quantity=line.quantity,
            unit_price=unit_price,
            lead_time_weeks=lead_time(line, demand),
            base_unit_price=base[line.position],
            surcharge_per_unit=cents(surcharge + setup / q),
            packaging_per_unit=cents(packaging / q),
            rebate_total=rebate,
        ))

    total = cents(sum((p.quantity * p.unit_price for p in priced), ZERO))
    return {
        "tender_reference": order.tender_reference,
        "decision": "bid",
        "currency": "EUR",
        "discount_percent": float(pct),
        "positions": [{k: (float(v) if isinstance(v, Decimal) else v) for k, v in vars(p).items()} for p in priced],
        "total_net": float(total),
    }
